S = input()

def countValidConfigurations():
    validCount = 0
    from itertools import product

    # Generate all possible combinations for '?'
    for combination in product('LR', repeat=S.count('?')):
        spoon = [False] * N
        combination_index = 0
        valid = True

        for p in P:
            if S[p] == 'L' or (S[p] == '?' and combination[combination_index] == 'L'):
                if not spoon[p]:
                    spoon[p] = True
                else:
                    valid = False
                    break
            elif S[p] == 'R' or (S[p] == '?' and combination[combination_index] == 'R'):
                if not spoon[(p+1)%N]:
                    spoon[(p+1)%N] = True
                else:
                    valid = False
                    break
            if S[p] == '?':
                combination_index += 1

        if valid:
            validCount += 1

    return validCount % MOD

